<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Image Preview | Library</title>
    <!-- Fonts -->
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&display=swap" rel="stylesheet">

    <!-- React & Babel for standalone browser usage -->
    <script src="https://unpkg.com/react@18/umd/react.production.min.js"></script>
    <script src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js"></script>
    <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>

    <style>
        :root {
            --color-bg: #f9fafb;
            --color-surface: #ffffff;
            --color-text: #111827;
            --color-muted-text: #6b7280;
            --color-border: #e5e7eb;
            --color-focus: #2563eb;
            --color-danger: #dc2626;
            --color-danger-hover: #b91c1c;
            --color-primary: #2563eb;
            --color-primary-hover: #1d4ed8;
            --radius: 8px;
            --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
        }

        body {
            font-family: 'Inter', system-ui, -apple-system, sans-serif;
            background-color: var(--color-bg);
            color: var(--color-text);
            margin: 0;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
        }

        * {
            box-sizing: border-box;
        }

        .container {
            max-width: 600px;
            width: 100%;
            padding: 2rem;
            background: var(--color-surface);
            border-radius: var(--radius);
            box-shadow: var(--shadow);
            text-align: center;
        }

        .image-preview {
            width: 100%;
            aspect-ratio: 16 / 9;
            background: #eef2f6;
            border-radius: var(--radius);
            display: flex;
            align-items: center;
            justify-content: center;
            margin-bottom: 1.5rem;
            overflow: hidden;
            border: 1px solid var(--color-border);
        }

        .image-preview img {
            width: 100%;
            height: 100%;
            object-fit: cover;
        }

        .image-info {
            margin-bottom: 1.5rem;
        }

        .image-info h1 {
            font-size: 1.25rem;
            font-weight: 600;
            margin: 0 0 0.5rem 0;
        }

        .image-info p {
            color: var(--color-muted-text);
            font-size: 0.875rem;
            margin: 0;
        }

        .btn {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            padding: 0.5rem 1rem;
            font-size: 0.875rem;
            font-weight: 500;
            border-radius: 6px;
            cursor: pointer;
            transition: all 0.2s;
            border: 1px solid transparent;
            font-family: inherit;
        }

        .btn:focus-visible {
            outline: 2px solid var(--color-focus);
            outline-offset: 2px;
        }

        /* paired with outline: transparent for forced-colors */
        @media (forced-colors: active) {
            .btn:focus-visible {
                outline: 2px solid ButtonBorder;
            }
        }

        .btn-danger {
            background-color: var(--color-danger);
            color: white;
        }

        .btn-danger:hover {
            background-color: var(--color-danger-hover);
        }

        .btn-outline {
            background-color: white;
            border: 1px solid var(--color-border);
            color: var(--color-text);
        }

        .btn-outline:hover {
            background-color: #f3f4f6;
        }

        /* Modal Styles */
        dialog {
            border: none;
            border-radius: 12px;
            padding: 0;
            box-shadow: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);
            max-width: 400px;
            width: 90%;
        }

        dialog::backdrop {
            background-color: rgba(0, 0, 0, 0.5);
            backdrop-filter: blur(4px);
        }

        .modal-content {
            padding: 1.5rem;
        }

        .modal-header {
            margin-bottom: 1rem;
        }

        .modal-header h2 {
            font-size: 1.125rem;
            font-weight: 600;
            margin: 0;
        }

        .modal-body {
            color: var(--color-muted-text);
            font-size: 0.875rem;
            line-height: 1.5;
            margin-bottom: 1.5rem;
        }

        .modal-footer {
            display: flex;
            justify-content: flex-end;
            gap: 0.75rem;
        }

        /* Accessibility: skip link if needed (though not strictly for this small app) */
        .skip-link {
            position: absolute;
            top: -40px;
            left: 0;
            background: var(--color-focus);
            color: white;
            padding: 8px;
            z-index: 100;
            transition: top 0.2s;
        }
        .skip-link:focus {
            top: 0;
        }
    </style>
</head>
<body>
    <div id="root"></div>

    <script type="text/babel">
        const { useState, useRef, useEffect } = React;

        const Modal = ({ isOpen, onClose, onConfirm, title, children }) => {
            const dialogRef = useRef(null);

            useEffect(() => {
                const dialog = dialogRef.current;
                if (!dialog) return;

                if (isOpen) {
                    if (!dialog.open) {
                        dialog.showModal();
                    }
                } else {
                    if (dialog.open) {
                        dialog.close();
                    }
                }
            }, [isOpen]);

            const handleClose = () => {
                onClose();
            };

            const handleCancel = () => {
                onClose();
            };

            const handleConfirm = () => {
                onConfirm();
                onClose();
            };

            // Handle native close (Escape key)
            useEffect(() => {
                const dialog = dialogRef.current;
                const handleNativeClose = () => {
                    onClose();
                };
                dialog.addEventListener('close', handleNativeClose);
                return () => dialog.removeEventListener('close', handleNativeClose);
            }, [onClose]);

            return (
                <dialog 
                    ref={dialogRef} 
                    aria-labelledby="modal-title"
                    aria-describedby="modal-description"
                >
                    <div className="modal-content">
                        <div className="modal-header">
                            <h2 id="modal-title">{title}</h2>
                        </div>
                        <div className="modal-body" id="modal-description">
                            {children}
                        </div>
                        <div className="modal-footer">
                            <button 
                                type="button" 
                                className="btn btn-outline" 
                                onClick={handleCancel}
                            >
                                Cancel
                            </button>
                            <button 
                                type="button" 
                                className="btn btn-danger" 
                                onClick={handleConfirm}
                            >
                                Delete Image
                            </button>
                        </div>
                    </div>
                </dialog>
            );
        };

        const App = () => {
            const [isModalOpen, setIsModalOpen] = useState(false);
            const [imageDeleted, setImageDeleted] = useState(false);

            const handleDeleteClick = () => {
                setIsModalOpen(true);
            };

            const handleConfirmDelete = () => {
                setImageDeleted(true);
                // In a real app, you'd call an API here
                console.log("Image deleted successfully");
            };

            if (imageDeleted) {
                return (
                    <main className="container">
                        <h1>Image Deleted</h1>
                        <p style={{ color: 'var(--color-muted-text)', marginBottom: '1.5rem' }}>
                            The image has been removed from your library.
                        </p>
                        <button 
                            className="btn btn-outline" 
                            onClick={() => setImageDeleted(false)}
                        >
                            Reset Demo
                        </button>
                    </main>
                );
            }

            return (
                <main className="container">
                    <div className="image-preview">
                        <img 
                            src="https://images.unsplash.com/photo-1472214103451-9374bd1c798e?auto=format&fit=crop&q=80&w=600" 
                            alt="Beautiful landscape with mountains and trees under a cloudy sky"
                        />
                    </div>
                    <div className="image-info">
                        <h1>Mountain Landscape</h1>
                        <p>Uploaded on May 6, 2026 • 2.4 MB</p>
                    </div>

                    <button 
                        type="button" 
                        className="btn btn-danger trigger" 
                        onClick={handleDeleteClick}
                    >
                        Delete Image
                    </button>

                    <Modal 
                        isOpen={isModalOpen} 
                        onClose={() => setIsModalOpen(false)}
                        onConfirm={handleConfirmDelete}
                        title="Delete Image?"
                    >
                        Are you sure you want to delete this image? This action cannot be undone and it will be permanently removed from your library.
                    </Modal>
                </main>
            );
        };

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<App />);
    </script>
</body>
</html>
