    <div id="root"></div>

    <script type="text/babel">
        const { useState, useRef, useEffect } = React;

        /**
         * A reusable accessible modal component using native <dialog>
         */
        const Modal = ({ isOpen, onClose, onConfirm, title, children }) => {
            const dialogRef = useRef(null);
            const previousFocusRef = useRef(null);

            useEffect(() => {
                const dialog = dialogRef.current;
                if (!dialog) return;

                if (isOpen) {
                    if (!dialog.open) {
                        previousFocusRef.current = document.activeElement;
                        dialog.showModal();
                    }
                } else {
                    if (dialog.open) {
                        dialog.close();
                    }
                }
            }, [isOpen]);

            // Handle native close events (e.g., Escape key)
            useEffect(() => {
                const dialog = dialogRef.current;
                const handleCancel = (e) => {
                    // Prevent default to handle closure via React state
                    e.preventDefault();
                    onClose();
                };

                dialog.addEventListener('cancel', handleCancel);
                return () => dialog.removeEventListener('cancel', handleCancel);
            }, [onClose]);

            return (
                <dialog 
                    ref={dialogRef} 
                    aria-labelledby="modal-title"
                    className="modal"
                >
                    <div className="modal-content">
                        <header className="modal-header">
                            <h2 id="modal-title">{title}</h2>
                        </header>
                        <div className="modal-body" id="modal-description">
                            {children}
                        </div>
                        <footer className="modal-footer">
                            <button 
                                type="button" 
                                className="btn btn-outline" 
                                onClick={onClose}
                            >
                                Cancel
                            </button>
                            <button 
                                type="button" 
                                className="btn btn-danger" 
                                onClick={onConfirm}
                            >
                                Delete Image
                            </button>
                        </footer>
                    </div>
                </dialog>
            );
        };

        const ImagePreview = ({ imageUrl, title, uploadDate, fileSize, onDelete }) => (
            <main className="container">
                <div className="image-preview">
                    <img 
                        src={imageUrl} 
                        alt={`Preview of ${title}`}
                    />
                </div>
                <div className="image-info">
                    <h1>{title}</h1>
                    <p>Uploaded on {uploadDate} • {fileSize}</p>
                </div>

                <button 
                    type="button" 
                    className="btn btn-danger trigger" 
                    onClick={onDelete}
                >
                    Delete Image
                </button>
            </main>
        );

        const SuccessMessage = ({ onReset }) => (
            <main className="container">
                <div style={{ padding: '2rem 0' }}>
                    <div style={{ 
                        fontSize: '3rem', 
                        marginBottom: '1rem', 
                        color: 'var(--color-primary)' 
                    }} aria-hidden="true">
                        ✓
                    </div>
                    <h1>Image Deleted</h1>
                    <p style={{ color: 'var(--color-muted-text)', marginBottom: '1.5rem' }}>
                        The image has been successfully removed from your library.
                    </p>
                    <button 
                        className="btn btn-outline" 
                        onClick={onReset}
                    >
                        Back to Library
                    </button>
                </div>
            </main>
        );

        const App = () => {
            const [isModalOpen, setIsModalOpen] = useState(false);
            const [isDeleted, setIsDeleted] = useState(false);

            const handleDelete = () => setIsModalOpen(true);
            const handleCancel = () => setIsModalOpen(false);

            const handleConfirmDelete = () => {
                setIsDeleted(true);
                setIsModalOpen(false);
                // In a real application, you'd trigger the actual deletion here
                console.log("Image deleted.");
            };

            const handleReset = () => setIsDeleted(false);

            if (isDeleted) {
                return <SuccessMessage onReset={handleReset} />;
            }

            return (
                <>
                    <ImagePreview 
                        imageUrl="https://images.unsplash.com/photo-1472214103451-9374bd1c798e?auto=format&fit=crop&q=80&w=800"
                        title="Mountain Landscape"
                        uploadDate="May 6, 2026"
                        fileSize="2.4 MB"
                        onDelete={handleDelete}
                    />

                    <Modal 
                        isOpen={isModalOpen} 
                        onClose={handleCancel}
                        onConfirm={handleConfirmDelete}
                        title="Delete Image?"
                    >
                        <p>Are you sure you want to delete <strong>Mountain Landscape</strong>? This action cannot be undone and the image will be permanently removed from your library.</p>
                    </Modal>
                </>
            );
        };

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<App />);
    </script>
