            transition: top 0.2s;
        }

        .skip-link:focus {
            top: 0;
        }

        .container {
            max-width: 600px;
            width: 100%;
            padding: 2.5rem;
            background: var(--color-surface);
            border-radius: var(--radius);
            box-shadow: var(--shadow);
            text-align: center;
        }

        .image-preview {
            width: 100%;
            aspect-ratio: 16 / 9;
            background: #eef2f6;
            border-radius: var(--radius);
            display: flex;
            align-items: center;
            justify-content: center;
            margin-bottom: 1.5rem;
            overflow: hidden;
            border: 1px solid var(--color-border);
        }

        .image-preview img {
            width: 100%;
            height: 100%;
            object-fit: cover;
        }

        .image-info {
            margin-bottom: 1.5rem;
        }

        .image-info h1 {
            font-size: 1.25rem;
            font-weight: 600;
