            --color-bg: #f9fafb;
            --color-surface: #ffffff;
            --color-text: #111827;
            --color-muted-text: #6b7280;
            --color-border: #e5e7eb;
            --color-focus: #2563eb;
            --color-danger: #dc2626;
            --color-danger-hover: #b91c1c;
            --color-primary: #2563eb;
            --color-primary-hover: #1d4ed8;
            --radius: 8px;
            --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
        }

        body {
            font-family: 'Inter', system-ui, -apple-system, sans-serif;
            background-color: var(--color-bg);
            color: var(--color-text);
            margin: 0;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
        }

        * {
            box-sizing: border-box;
        }

        /* Skip Link */
        .skip-link {
            position: absolute;
            top: -100px;
            left: 0;
            background: var(--color-primary);
            color: white;
            padding: 1rem;
            z-index: 1000;
            text-decoration: none;
            font-weight: 500;
            border-radius: 0 0 var(--radius) 0;
            transition: top 0.2s;
        }

        .skip-link:focus {
            top: 0;
        }

        .container {
            max-width: 600px;
            width: 100%;
            padding: 2.5rem;
            background: var(--color-surface);
            border-radius: var(--radius);
            box-shadow: var(--shadow);
            text-align: center;
        }

        .image-preview {
            width: 100%;
            aspect-ratio: 16 / 9;
            background: #eef2f6;
            border-radius: var(--radius);
            display: flex;
            align-items: center;
            justify-content: center;
            margin-bottom: 1.5rem;
            overflow: hidden;
            border: 1px solid var(--color-border);
        }

        .image-preview img {
            width: 100%;
            height: 100%;
            object-fit: cover;
        }

        .image-info {
            margin-bottom: 1.5rem;
        }

        .image-info h1 {
            font-size: 1.25rem;
            font-weight: 600;
            margin: 0 0 0.5rem 0;
        }

        .image-info p {
            color: var(--color-muted-text);
            font-size: 0.875rem;
            margin: 0;
        }

        .btn {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            padding: 0.5rem 1rem;
            font-size: 0.875rem;
            font-weight: 500;
            border-radius: 6px;
            cursor: pointer;
            transition: all 0.2s;
            border: 1px solid transparent;
            font-family: inherit;
        }

        .btn:focus-visible {
            outline: 2px solid var(--color-focus);
            outline-offset: 2px;
        }

        /* paired with outline: transparent for forced-colors */
        @media (forced-colors: active) {
            .btn:focus-visible {
                outline: 2px solid ButtonBorder;
            }
        }

        .btn-danger {
            background-color: var(--color-danger);
            color: white;
        }

        .btn-danger:hover {
            background-color: var(--color-danger-hover);
        }

        .btn-outline {
            background-color: white;
            border: 1px solid var(--color-border);
            color: var(--color-text);
        }

        .btn-outline:hover {
            background-color: #f3f4f6;
        }

        /* Modal Styles */
        dialog {
            border: none;
            border-radius: 12px;
            padding: 0;
            box-shadow: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);
            max-width: 400px;
            width: 90%;
        }

        dialog::backdrop {
            background-color: rgba(0, 0, 0, 0.5);
            backdrop-filter: blur(4px);
        }

        .modal-content {
            padding: 1.5rem;
        }

        .modal-header {
            margin-bottom: 1rem;
        }

        .modal-header h2 {
            font-size: 1.125rem;
            font-weight: 600;
            margin: 0;
        }

        .modal-body {
            color: var(--color-muted-text);
            font-size: 0.875rem;
            line-height: 1.5;
            margin-bottom: 1.5rem;
        }

        .modal-footer {
            display: flex;
            justify-content: flex-end;
            gap: 0.75rem;
        }
    </style>
</head>
<body>
    <a href="#main-content" class="skip-link">Skip to main content</a>
    <div id="root"></div>

    <script type="text/babel">
        const { useState, useRef, useEffect } = React;

        /**
         * A reusable accessible modal component using native <dialog>
         */
        const Modal = ({ isOpen, onClose, onConfirm, title, children }) => {
            const dialogRef = useRef(null);

            useEffect(() => {
                const dialog = dialogRef.current;
                if (!dialog) return;

                if (isOpen) {
                    if (!dialog.open) {
                        dialog.showModal();
                    }
                } else {
                    if (dialog.open) {
                        dialog.close();
                    }
                }
            }, [isOpen]);

            // Handle native close events (e.g., Escape key)
            useEffect(() => {
                const dialog = dialogRef.current;
                const handleCancel = (e) => {
                    e.preventDefault();
                    onClose();
                };

                dialog.addEventListener('cancel', handleCancel);
                return () => dialog.removeEventListener('cancel', handleCancel);
            }, [onClose]);

            return (
                <dialog 
                    ref={dialogRef} 
                    aria-labelledby="modal-title"
                    aria-describedby="modal-description"
                    className="modal"
                >
                    <div className="modal-content">
                        <header className="modal-header">
                            <h2 id="modal-title">{title}</h2>
                        </header>
                        <div className="modal-body" id="modal-description">
                            {children}
                        </div>
                        <footer className="modal-footer">
                            <button 
                                type="button" 
                                className="btn btn-outline" 
                                onClick={onClose}
                            >
                                Cancel
                            </button>
                            <button 
                                type="button" 
                                className="btn btn-danger" 
                                onClick={onConfirm}
                            >
                                Delete Image
                            </button>
                        </footer>
                    </div>
                </dialog>
            );
        };

        const ImagePreview = ({ imageUrl, title, uploadDate, fileSize, onDelete }) => (
            <main className="container" id="main-content" tabIndex="-1">
                <div className="image-preview">
                    <img 
                        src={imageUrl} 
                        alt={`Preview of ${title}`}
                    />
                </div>
                <div className="image-info">
                    <h1>{title}</h1>
                    <p>Uploaded on {uploadDate} • {fileSize}</p>
                </div>

                <button 
                    type="button" 
                    className="btn btn-danger trigger" 
                    onClick={onDelete}
                >
                    Delete Image
                </button>
            </main>
        );

        const SuccessMessage = ({ onReset }) => {
            const headingRef = useRef(null);

            useEffect(() => {
                // Move focus to the heading for screen readers
                headingRef.current?.focus();
            }, []);

            return (
                <main className="container" id="main-content" tabIndex="-1">
                    <div style={{ padding: '2rem 0' }}>
                        <div style={{ 
                            fontSize: '3rem', 
                            marginBottom: '1rem', 
                            color: 'var(--color-primary)' 
                        }} aria-hidden="true">
                            ✓
                        </div>
                        <h1 ref={headingRef} tabIndex="-1" style={{ outline: 'none' }}>
                            Image Deleted
                        </h1>
                        <p style={{ color: 'var(--color-muted-text)', marginBottom: '1.5rem' }}>
                            The image has been successfully removed from your library.
                        </p>
                        <button 
                            className="btn btn-outline" 
                            onClick={onReset}
                        >
                            Back to Library
                        </button>
                    </div>
                </main>
            );
        };

        const App = () => {
            const [isModalOpen, setIsModalOpen] = useState(false);
            const [isDeleted, setIsDeleted] = useState(false);

            const handleDelete = () => setIsModalOpen(true);
            const handleCancel = () => setIsModalOpen(false);

            const handleConfirmDelete = () => {
                setIsDeleted(true);
                setIsModalOpen(false);
                // In a real application, you'd trigger the actual deletion here
                console.log("Image deleted.");
            };

            const handleReset = () => setIsDeleted(false);

            if (isDeleted) {
                return <SuccessMessage onReset={handleReset} />;
            }

            return (
                <>
                    <ImagePreview 
                        imageUrl="https://images.unsplash.com/photo-1472214103451-9374bd1c798e?auto=format&fit=crop&q=80&w=800"
                        title="Mountain Landscape"
                        uploadDate="May 6, 2026"
                        fileSize="2.4 MB"
                        onDelete={handleDelete}
                    />

                    <Modal 
                        isOpen={isModalOpen} 
                        onClose={handleCancel}
                        onConfirm={handleConfirmDelete}
                        title="Delete Image?"
                    >
                        <p>Are you sure you want to delete <strong>Mountain Landscape</strong>? This action cannot be undone and the image will be permanently removed from your library.</p>
                    </Modal>
                </>
            );
        };

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<App />);
    </script>
</body>
</html>
